defense.vulnerable_config:
-- UTL_FILE reachable by everyone + a wide-open directory:
GRANT EXECUTE ON SYS.UTL_FILE TO PUBLIC;
-- legacy parameter (init.ora):
utl_file_dir = *
-- or a DIRECTORY object pointing at the web root, writable by a low-priv account:
CREATE DIRECTORY web AS '/var/www/html';
GRANT READ, WRITE ON DIRECTORY web TO app_user;

defense.secure_config:
-- Remove broad UTL_FILE access:
REVOKE EXECUTE ON SYS.UTL_FILE FROM PUBLIC;
-- Drop the legacy wildcard; use scoped DIRECTORY objects instead of utl_file_dir:
ALTER SYSTEM RESET utl_file_dir SCOPE=SPFILE;
-- Grant directory access only where required, least-privilege, never the web root:
CREATE DIRECTORY data_load AS '/opt/oracle/import';
GRANT READ ON DIRECTORY data_load TO app_user;   -- add WRITE only if truly needed
